#define _POSIX_C_SOURCE 200809L
#include <stdlib.h>
#include <stdio.h>
#include <assert.h>
#include <string.h>
static size_t calls, site, outstanding;
static int sticky;
static void *inject(size_t n) {
    ++calls;
    if(site && (calls==site || (sticky && calls>=site))) return NULL;
    void *p=malloc(n); if(p) ++outstanding; return p;
}
static void release(void *p) { if(p) { assert(outstanding); --outstanding; free(p); } }
#define free release
#include "/src/core/src/context/interpreter.c"
#undef free
int main(void) {
    size_t counts[]={1,8,16};
    for(int structured=0;structured<2;structured++) for(size_t c=0;c<3;c++) {
        rc_interpreter w={.tokens=4096,.structured_output=structured};
        strcpy(w.model,"independent-\"model\\");
        rc_interpreter_input in={.revision=UINT64_MAX,.evidence_count=counts[c]};
        const char *sources[]={"executor","exposed_plan","model_claim","coverage_notice"};
        for(size_t j=0;j<in.evidence_count;j++) {
            snprintf(in.evidence[j].id,sizeof(in.evidence[j].id),"ind-%zu-\"\\\n\xc3\xa9",j);
            strcpy(in.evidence[j].source,sources[j%4]);
            if(c==0) strcpy(in.evidence[j].text,"independent \"quotes\" \\ tab\t newline\n UTF8 \xf0\x9f\x98\x80");
            else { for(size_t k=0;k<sizeof(in.evidence[j].text)-1;k++) in.evidence[j].text[k]="\"\\\n\t abc"[k%8]; }
        }
        site=calls=0; json_set_alloc_funcs(inject,release);
        char *s=request_body(&w,&in); assert(s);
        size_t total=calls;
        printf("{\"structured\":%d,\"count\":%zu,\"site\":0,\"mode\":0,\"body\":%s}\n",structured,in.evidence_count,s);
        release(s); assert(!outstanding);
        for(sticky=0;sticky<2;sticky++) for(size_t i=1;i<=total+1;i++) {
            site=i; calls=0;
            s=request_body(&w,&in);
            printf("{\"structured\":%d,\"count\":%zu,\"site\":%zu,\"mode\":%d,\"body\":%s}\n",structured,in.evidence_count,i,sticky,s?s:"null");
            release(s); assert(!outstanding);
        }
        fprintf(stderr,"structured=%d count=%zu allocation_sites=%zu modes=2 live=%zu\n",structured,in.evidence_count,total,outstanding);
    }
    json_set_alloc_funcs(malloc,free);
    return 0;
}
